    { subject: "Social Studies", type: "Geography", tagText: "Plateaus", question: "जगातील सर्वात मोठे व उंच पठार कोणते ज्यास 'जगाचे छप्पर' (Roof of the World) म्हटले जाते?", options: ["तिबेटचे पठार (पामीरचे पठार)", "दख्खनचे पठार", "कोलोरॅडोचे पठार", "ब्राझीलचे पठार"], answer: 0, explanation: "मध्य आशियातील पामीर/तिबेटच्या विस्तीर्ण व अतिउंच पठाराला 'जगाचे छप्पर' म्हटले जाते." },
    { subject: "Social Studies", type: "History", tagText: "Social Movement", question: "महाराष्ट्रात मुलींची पहिली शाळा 1848 मध्ये पुण्यात कोणी सुरू केली?", options: ["महात्मा जोतीराव फुले व सावित्रीबाई फुले", "महर्षी कर्वे", "पंडिता रमाबाई", "न्यायमूर्ती रानडे"], answer: 0, explanation: "1848 मध्ये भिडे वाड्यात महात्मा फुले आणि क्रांतीज्योती सावित्रीबाई फुले यांनी मुलींची पहिली ऐतिहासिक शाळा काढली." }
