    { subject: "Social Studies", type: "Geography", tagText: "Western Ghats", question: "सह्याद्री पर्वतातील महाराष्ट्रातील सर्वोच्च शिखर 'कळसूबाई' ची उंची किती मीटर आहे?", options: ["1646 मीटर", "1567 मीटर", "1438 मीटर", "1720 मीटर"], answer: 0, explanation: "अहमदनगर व नाशिक जिल्ह्यांच्या सीमेवर वसलेले कळसूबाई शिखर 1646 मीटर (5400 फूट) उंच असून महाराष्ट्रातील सर्वोच्च शिखर आहे." },
    { subject: "Social Studies", type: "Economics", tagText: "GST", question: "भारतात 'वस्तू व सेवा कर' (GST) कोणत्या वर्षी आणि तारखेपासून देशभरात लागू करण्यात आला?", options: ["1 जुलै 2017", "1 एप्रिल 2015", "8 नोव्हेंबर 2016", "15 ऑगस्ट 2018"], answer: 0, explanation: "'एक देश, एक कर' या उद्देशाने 1 जुलै 2017 पासून 101 व्या घटनादुरुस्तीद्वारे भारतात GST लागू झाला." }
